import * as sdk from '@hermes/plugin-sdk'
import { jsx, jsxs } from 'react/jsx-runtime'

const host = sdk.host
const atom = sdk.atom
const useValue = sdk.useValue
const Tip = sdk.Tip
const Button = sdk.Button || 'button'
const ScrollArea = sdk.ScrollArea || 'div'
const EmptyState = sdk.EmptyState || 'div'
const Badge = sdk.Badge || 'span'
const Switch = sdk.Switch || 'button'
const Separator = sdk.Separator || 'hr'

// ---- src/providers.js ----
// Definition provider registry, per-session cache and fallback chain.
// Plain ESM with no imports so it can be concatenated into plugin.js.

const DEFAULT_ORDER = ['inline', 'session', 'static', 'mdn', 'wiktionary', 'wikipedia', 'coined', 'llm'];
const DEFAULT_DISABLED = ['llm'];

function normalizeTerm(term) {
  return String(term ?? '').trim().replace(/\s+/g, ' ').toLowerCase();
}

function clipWords(text, maxWords) {
  const words = String(text ?? '').trim().split(/\s+/).filter(Boolean);
  if (!(maxWords > 0)) return '';
  if (words.length <= maxWords) return words.join(' ');
  return words.slice(0, maxWords).join(' ') + '\u2026';
}

const sessionKey = (sessionId) => String(sessionId ?? '');
const termKey = (term, sessionId) => normalizeTerm(term) + '\0' + sessionKey(sessionId);
const isThenable = (v) => v != null && typeof v.then === 'function';
const hasText = (v) => typeof v === 'string' && v.trim() !== '';

function isSuccess(def) {
  return def != null && typeof def === 'object' && (hasText(def.short) || hasText(def.long));
}

function createRegistry(options = {}) {
  const providers = new Map();
  let order = DEFAULT_ORDER.slice();
  let disabled = new Set(DEFAULT_DISABLED);
  const uses = new Map();
  const cache = new Map();
  let useCounter = 0;

  const known = (id) => providers.has(id) || order.includes(id);
  const enabledChain = () => order.filter((id) => providers.has(id) && !disabled.has(id)).map((id) => providers.get(id));

  function attempt(provider, term, ctx) {
    try {
      if (!provider.canResolve(term, ctx)) return undefined;
      return provider.resolve(term, ctx);
    } catch {
      return undefined;
    }
  }

  function accept(provider, def) {
    if (!isSuccess(def)) return null;
    return def.providerId ? def : { ...def, providerId: provider.id };
  }

  const registry = {
    register(provider) {
      providers.set(provider.id, provider);
      if (!order.includes(provider.id)) order.push(provider.id);
      return registry;
    },
    list() {
      return order.filter((id) => providers.has(id)).map((id) => providers.get(id));
    },
    get(id) {
      return providers.get(id) ?? null;
    },
    setOrder(ids) {
      const named = [];
      for (const id of Array.isArray(ids) ? ids : []) if (!named.includes(id)) named.push(id);
      order = named.concat(order.filter((id) => !named.includes(id)));
      cache.clear();
    },
    setDisabled(ids) {
      disabled = new Set((Array.isArray(ids) ? ids : []).filter(known));
      for (const [key, entry] of cache) if (disabled.has(entry.def.providerId)) cache.delete(key);
    },
    isDisabled(id) {
      return disabled.has(id);
    },
    recordUse({ name, def, sessionId, source, attrs, surrounding } = {}) {
      if (!hasText(name)) return null;
      // The quote is only ever a real surrounding sentence, never the definition.
      const quote = hasText(surrounding) ? surrounding : null;
      const key = termKey(name, sessionId);
      if (!uses.has(key)) uses.set(key, []);
      const list = uses.get(key);

      // Render is a side effect that repeats (streaming growth, settle flip), so
      // an identical or prefix-related source is the same occurrence.
      if (hasText(source)) {
        const existing = list.find(
          (u) => hasText(u.source) && (u.source.startsWith(source) || source.startsWith(u.source)),
        );
        if (existing) {
          const longer = source.length > existing.source.length;
          const gainsQuote = quote !== null && existing.quote === null;
          if (longer || gainsQuote) {
            if (longer) existing.source = source;
            if (hasText(def)) existing.def = def;
            if (quote !== null) {
              existing.surrounding = surrounding;
              existing.quote = quote;
            }
            if (attrs != null) existing.attrs = attrs;
          }
          return existing;
        }
      }

      const use = {
        name,
        def: def ?? null,
        sessionId: sessionId ?? null,
        source: source ?? null,
        attrs: attrs ?? null,
        surrounding: surrounding ?? null,
        at: useCounter++,
        quote,
      };
      list.push(use);
      return use;
    },
    usesFor(name, sessionId) {
      return (uses.get(termKey(name, sessionId)) ?? []).slice();
    },
    firstUse(name, sessionId) {
      return (uses.get(termKey(name, sessionId)) ?? [])[0] ?? null;
    },
    lookupSync(term, ctx) {
      const full = { ...ctx, registry };
      for (const provider of enabledChain()) {
        const out = attempt(provider, term, full);
        if (out === undefined || isThenable(out)) continue;
        const def = accept(provider, out);
        if (def) return def;
      }
      return null;
    },
    async lookup(term, ctx) {
      const key = termKey(term, ctx?.sessionId);
      const hit = cache.get(key);
      if (hit && !disabled.has(hit.def.providerId)) return hit.def;
      const full = { ...ctx, registry };
      for (const provider of enabledChain()) {
        let out = attempt(provider, term, full);
        if (out === undefined) continue;
        if (isThenable(out)) {
          try {
            out = await out;
          } catch {
            continue;
          }
        }
        const def = accept(provider, out);
        if (def) {
          cache.set(key, { session: sessionKey(ctx?.sessionId), def });
          return def;
        }
      }
      return null;
    },
    clearCache(sessionId) {
      if (sessionId === undefined) return cache.clear();
      const session = sessionKey(sessionId);
      for (const [key, entry] of cache) if (entry.session === session) cache.delete(key);
    },
    peekCache(term, sessionId) {
      const def = cache.get(termKey(term, sessionId))?.def ?? null;
      return def && !disabled.has(def.providerId) ? def : null;
    },
  };

  for (const provider of options.providers ?? []) registry.register(provider);
  return registry;
}

// ---- src/inline-provider.js ----
const inlineDef = (ctx) => {
  const def = ctx?.attrs?.def;
  return typeof def === 'string' ? def.trim() : '';
};

function createInlineProvider() {
  return {
    id: 'inline',
    label: 'Inline directive',
    canResolve: (term, ctx) => inlineDef(ctx) !== '',
    resolve(term, ctx) {
      const def = inlineDef(ctx);
      if (!def) return null;
      return {
        short: clipWords(def, 25),
        long: clipWords(def, 120),
        source: 'Inline directive',
        kind: 'standard',
        providerId: 'inline',
        url: null,
        firstUse: null,
      };
    },
  };
}

// ---- src/session-glossary.js ----
const hasText_session_glossary = (v) => typeof v === 'string' && v.trim() !== '';

function createSessionProvider(boundRegistry) {
  let bound = boundRegistry ?? null;
  const reg = (ctx) => ctx?.registry ?? bound;
  const storedDef = (term, ctx) => {
    const registry = reg(ctx);
    if (!registry) return null;
    const use = registry.usesFor(term, ctx?.sessionId ?? null).find((u) => hasText_session_glossary(u.def));
    return use ? use.def.trim() : null;
  };

  return {
    id: 'session',
    label: 'Session glossary',
    bind(registry) {
      bound = registry;
    },
    canResolve(term, ctx) {
      const registry = reg(ctx);
      if (!registry) return false;
      return storedDef(term, ctx) !== null || registry.firstUse(term, ctx?.sessionId ?? null) !== null;
    },
    resolve(term, ctx) {
      const def = storedDef(term, ctx);
      if (def === null) return null;
      const first = reg(ctx).firstUse(term, ctx?.sessionId ?? null);
      return {
        short: clipWords(def, 25),
        long: clipWords(def, 120),
        source: 'Session glossary',
        kind: 'standard',
        providerId: 'session',
        url: null,
        firstUse: first ? { quote: first.quote, sessionId: first.sessionId } : null,
      };
    },
  };
}

// ---- src/static-glossary.js ----
const DEFAULT_GLOSSARY = [
  { term: 'monoid', def: 'An associative binary operation together with an identity element, such as addition with zero.' },
  { term: 'semigroup', def: 'A set with an associative binary operation, like a monoid but without a required identity element.' },
  { term: 'idempotent', def: 'Describes an operation that gives the same result whether it is applied once or many times.' },
  { term: 'CRDT', def: 'A conflict-free replicated data type, a structure whose replicas can be updated independently and always merge to the same state.' },
  { term: 'backpressure', def: 'A signal from a slow consumer telling a fast producer to slow down so buffers do not overflow.' },
  { term: 'closure', def: 'A function bundled with the variables from the scope where it was defined, so it can use them later.' },
  { term: 'currying', def: 'Turning a function of several arguments into a chain of functions that each take one argument.' },
  { term: 'memoization', def: 'Caching the result of a function call by its arguments so repeated calls return the stored value.' },
  { term: 'debounce', def: 'Delaying an action until a burst of events has stopped for a set quiet period.' },
  { term: 'throttle', def: 'Limiting how often an action may run, for example at most once per time interval.' },
  { term: 'referential transparency', def: 'A property of an expression that can be replaced by its value without changing the behavior of the program.' },
  { term: 'side effect', def: 'Any observable change an operation makes beyond returning a value, such as writing to disk or mutating state.' },
  { term: 'eventual consistency', def: 'A guarantee that replicas will converge to the same value if updates stop, though reads may be stale meanwhile.' },
  { term: 'vector clock', def: 'A set of per-node counters used to order events and detect concurrent updates in a distributed system.' },
  { term: 'Merkle tree', def: 'A tree of hashes where each node hashes its children, allowing efficient verification of large data sets.' },
  { term: 'CAP theorem', def: 'The result that a distributed system cannot guarantee consistency, availability, and partition tolerance all at once.' },
  { term: 'reentrancy', def: 'The property of code that can be safely called again before an earlier call has finished.' },
  { term: 'soundness', def: 'The guarantee that a type system or proof system never accepts a program or claim that is actually wrong.' },
  { term: 'variance', def: 'How subtyping of type parameters relates to subtyping of the generic types built from them.' },
  { term: 'lifetime', def: 'The span of program execution during which a reference or value is guaranteed to remain valid.' },
  { term: 'borrow checker', def: 'A compiler pass, notably in Rust, that enforces ownership and borrowing rules to prevent invalid memory access.' },
  { term: 'continuation', def: 'A representation of the rest of a computation, which can be captured and resumed later.' },
  { term: 'trampoline', def: 'A loop that repeatedly calls returned thunks so deep recursion runs without growing the call stack.' },
  { term: 'type class', def: 'A set of operations that a type can implement, letting functions be written generically over any type that supports them.' },
  { term: 'higher-kinded type', def: 'A type that abstracts over type constructors, such as a generic over List or Option rather than over plain types.' },
  { term: 'unification', def: 'Finding a substitution that makes two symbolic expressions identical, used in type inference and logic programming.' },
  { term: 'narrowing', def: 'Refining a value type to a more specific one based on checks the compiler can see, such as a type test in a branch.' },
  { term: 'effect system', def: 'A type system feature that tracks which side effects a function may perform in its signature.' },
  { term: 'orthogonal persistence', def: 'A design where data lives beyond program runs without code treating persistent and temporary data differently.' },
  { term: 'nonce', def: 'A number used once, supplied to an operation so that old messages cannot be replayed or reused.' },
  { term: 'monad', def: 'A design pattern that wraps values in a context and chains operations on them, handling the context such as failure or state automatically.' },
  { term: 'functor', def: 'A container type that supports mapping a function over its contents while keeping the container structure unchanged.' },
  { term: 'hoisting', def: 'JavaScript behavior where declarations are processed before code runs, so they can be used earlier in their scope than where they are written.' },
  { term: 'idempotency', def: 'The property that repeating an operation has the same effect as doing it once, which makes retries safe.' },
  { term: 'flexbox', def: 'A CSS layout model that arranges items along a row or column and distributes the space between them.' },
  { term: 'grid', def: 'A CSS layout model that places items into rows and columns of a two-dimensional grid.' },
  { term: 'polyfill', def: 'Code that adds a modern feature to an older environment that does not support it natively.' },
  { term: 'mutex', def: 'A lock that lets only one thread at a time enter a critical section of code.' },
  { term: 'deadlock', def: 'A state where two or more tasks each wait for the other to release a resource, so none can proceed.' },
  { term: 'race condition', def: 'A bug where the result depends on the unpredictable timing or ordering of concurrent operations.' },
  { term: 'immutability', def: 'The property of data that cannot be changed after creation, so updates produce new values instead.' },
  { term: 'lazy evaluation', def: 'Delaying the computation of a value until it is actually needed, and then reusing the result.' },
  { term: 'event loop', def: 'A loop that waits for events or queued tasks and runs their handlers one at a time.' },
  { term: 'middleware', def: 'Code that sits between a request and its handler and can inspect, change, or short-circuit the exchange.' },
  { term: 'tail call', def: 'A function call made as the very last step of another function, which can reuse the current stack frame.' },
];

function toMap(entries) {
  const map = new Map();
  if (Array.isArray(entries)) {
    for (const e of entries) if (e && typeof e.def === 'string') map.set(normalizeTerm(e.term), e.def);
  } else if (entries && typeof entries === 'object') {
    for (const [term, def] of Object.entries(entries)) if (typeof def === 'string') map.set(normalizeTerm(term), def);
  }
  return map;
}

// Conservative inflections of one lowercase word: itself first, then singular
// forms (ies -> y, es, s but not ss) and plural forms. A form only counts when
// it is an actual glossary key, so nothing is invented. Mirrors _inflections in
// __init__.py.
function wordForms(word) {
  const w = word.toLowerCase();
  const out = [w];
  if (w.length > 3 && w.endsWith('ies')) out.push(`${w.slice(0, -3)}y`);
  if (w.length > 2 && w.endsWith('s') && !w.endsWith('ss')) out.push(w.slice(0, -1));
  if (w.length > 3 && w.endsWith('es')) out.push(w.slice(0, -2));
  if (w.length > 2 && w.endsWith('y') && !'aeiou'.includes(w[w.length - 2])) out.push(`${w.slice(0, -1)}ies`);
  if (!w.endsWith('s')) out.push(`${w}s`);
  if (/(?:s|x|z|ch|sh)$/.test(w)) out.push(`${w}es`);
  return out;
}

function phraseHit(map, words) {
  const head = words.slice(0, -1).map((w) => w.toLowerCase());
  for (const form of wordForms(words[words.length - 1])) {
    const def = map.get([...head, form].join(' '));
    if (def && def.trim()) return def.trim();
  }
  return null;
}

// Full phrase, then the head noun (and longer trailing sub-terms), then any
// other sub-term, so "CSS Flexbox" finds "flexbox" and "Monads" finds "monad".
function findDefinition(map, term) {
  const words = normalizeTerm(term).split(' ').filter(Boolean);
  if (words.length === 0) return null;
  const whole = phraseHit(map, words);
  if (whole || words.length === 1) return whole;
  for (let n = words.length - 1; n >= 1; n--) {
    const hit = phraseHit(map, words.slice(words.length - n));
    if (hit) return hit;
  }
  for (let n = words.length - 1; n >= 1; n--) {
    for (let i = 0; i + n < words.length; i++) {
      const hit = phraseHit(map, words.slice(i, i + n));
      if (hit) return hit;
    }
  }
  return null;
}

function lookupGlossary(term, entries) {
  return findDefinition(toMap(entries), term);
}

function createStaticProvider(entries = DEFAULT_GLOSSARY) {
  const bundled = toMap(entries);
  const find = (term, ctx) => {
    const user = lookupGlossary(term, ctx?.userGlossary);
    if (user) return { def: user, source: 'User glossary' };
    const def = findDefinition(bundled, term);
    return def ? { def, source: 'Static glossary' } : null;
  };

  return {
    id: 'static',
    label: 'Static glossary',
    canResolve: (term, ctx) => find(term, ctx) !== null,
    resolve(term, ctx) {
      const hit = find(term, ctx);
      if (!hit) return null;
      return {
        short: clipWords(hit.def, 25),
        long: clipWords(hit.def, 120),
        source: hit.source,
        kind: 'standard',
        providerId: 'static',
        url: null,
        firstUse: null,
      };
    },
  };
}

// ---- src/wiki-provider.js ----
const hasText_wiki_provider = (v) => typeof v === 'string' && v.trim() !== '';
const isObject = (v) => v != null && typeof v === 'object' && !Array.isArray(v);

function requestInit() {
  const init = { headers: { Accept: 'application/json' } };
  if (typeof AbortSignal !== 'undefined' && typeof AbortSignal.timeout === 'function') {
    init.signal = AbortSignal.timeout(4000);
  }
  return init;
}

// Throws only when ctx.fetch itself throws; HTTP errors and bad JSON give null.
async function getJson(url, ctx) {
  const res = await ctx.fetch(url, requestInit());
  const ok = res && (res.ok ?? (res.status >= 200 && res.status < 300));
  if (!ok) return null;
  try {
    return await res.json();
  } catch {
    return null;
  }
}

function fromRest(payload, providerId, defaults) {
  if (!isObject(payload) || !(hasText_wiki_provider(payload.short) || hasText_wiki_provider(payload.long))) return null;
  const long = hasText_wiki_provider(payload.long) ? payload.long : payload.short;
  const short = hasText_wiki_provider(payload.short) ? payload.short : payload.long;
  return {
    ...payload,
    short: clipWords(short, 25),
    long: clipWords(long, 120),
    source: hasText_wiki_provider(payload.source) ? payload.source : defaults.source,
    kind: payload.kind ?? defaults.kind,
    providerId,
    url: payload.url ?? null,
    firstUse: payload.firstUse ?? null,
  };
}

async function restLookup(ctx, source, term, providerId, label) {
  if (typeof ctx.rest !== 'function') return null;
  try {
    const payload = await ctx.rest('/lookup?source=' + source + '&term=' + encodeURIComponent(term));
    return fromRest(payload, providerId, { source: label, kind: 'standard' });
  } catch {
    return null;
  }
}

function createRemoteProvider({ id, label, restSource, urlFor, parse }) {
  return {
    id,
    label,
    canResolve(term, ctx) {
      return (typeof ctx?.fetch === 'function' || typeof ctx?.rest === 'function') && normalizeTerm(term) !== '';
    },
    async resolve(term, ctx) {
      let data = null;
      let threw = typeof ctx?.fetch !== 'function';
      if (!threw) {
        try {
          data = await getJson(urlFor(term), ctx);
        } catch {
          threw = true;
        }
      }
      if (threw) return restLookup(ctx ?? {}, restSource, term, id, label);
      if (data == null) return null;
      try {
        return parse(data, term);
      } catch {
        return null;
      }
    },
  };
}

function createWikipediaProvider() {
  return createRemoteProvider({
    id: 'wikipedia',
    label: 'Wikipedia',
    restSource: 'wikipedia',
    urlFor: (term) => 'https://en.wikipedia.org/api/rest_v1/page/summary/' + encodeURIComponent(term),
    parse(data, term) {
      if (!isObject(data) || data.type === 'disambiguation' || data.type === 'disambig') return null;
      if (!hasText_wiki_provider(data.extract)) return null;
      const page = data.content_urls?.desktop?.page;
      return {
        short: clipWords(data.extract, 25),
        long: clipWords(data.extract, 120),
        source: 'Wikipedia',
        kind: 'standard',
        providerId: 'wikipedia',
        url: hasText_wiki_provider(page) ? page : 'https://en.wikipedia.org/wiki/' + encodeURIComponent(hasText_wiki_provider(data.title) ? data.title : term),
        firstUse: null,
      };
    },
  });
}

const ENTITIES = { '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'" };

function cleanHtml(html) {
  return String(html ?? '')
    .replace(/<[^>]+>/g, '')
    .replace(/&(?:amp|lt|gt|quot|#39);/g, (m) => ENTITIES[m])
    .replace(/\s+/g, ' ')
    .trim();
}

function createWiktionaryProvider() {
  return createRemoteProvider({
    id: 'wiktionary',
    label: 'Wiktionary',
    restSource: 'wiktionary',
    urlFor: (term) => 'https://en.wiktionary.org/api/rest_v1/page/definition/' + encodeURIComponent(term),
    parse(data, term) {
      if (!isObject(data)) return null;
      const entries = Array.isArray(data.en) ? data.en : Object.values(data).find(Array.isArray);
      if (!entries) return null;
      for (const entry of entries) {
        for (const d of Array.isArray(entry?.definitions) ? entry.definitions : []) {
          const text = cleanHtml(d?.definition);
          if (text) {
            return {
              short: clipWords(text, 25),
              long: clipWords(text, 120),
              source: 'Wiktionary',
              kind: 'standard',
              providerId: 'wiktionary',
              url: 'https://en.wiktionary.org/wiki/' + encodeURIComponent(term),
              firstUse: null,
            };
          }
        }
      }
      return null;
    },
  });
}

// ---- src/mdn-provider.js ----
const hasText_mdn_provider = (v) => typeof v === 'string' && v.trim() !== '';
const fold = (s) => String(s ?? '').trim().replace(/\s+/g, ' ').toLowerCase();
const strip = (s) => fold(String(s ?? '').replace(/[^\p{L}\p{N}\s]/gu, ' ')).trim();

function looseMatch(title, term) {
  const t = fold(title);
  const q = fold(term);
  return t === q || t.startsWith(q + ' ');
}

function pickDocument(documents, term) {
  if (!Array.isArray(documents) || documents.length === 0) return null;
  if (documents[0] && looseMatch(documents[0].title, term)) return documents[0];
  const q = strip(term);
  return q ? documents.find((d) => d && strip(d.title) === q) ?? null : null;
}

function createMdnProvider() {
  return createRemoteProvider({
    id: 'mdn',
    label: 'MDN',
    restSource: 'mdn',
    urlFor: (term) => 'https://developer.mozilla.org/api/v1/search?q=' + encodeURIComponent(term) + '&locale=en-US',
    parse(data, term) {
      const doc = pickDocument(data?.documents, term);
      if (!doc || !hasText_mdn_provider(doc.summary)) return null;
      return {
        short: clipWords(doc.summary, 25),
        long: clipWords(doc.summary, 120),
        source: 'MDN',
        kind: 'standard',
        providerId: 'mdn',
        url: hasText_mdn_provider(doc.mdn_url) ? 'https://developer.mozilla.org' + doc.mdn_url : null,
        firstUse: null,
      };
    },
  });
}

// ---- src/coined-provider.js ----
const hasText_coined_provider = (v) => typeof v === 'string' && v.trim() !== '';
const NOT_FOUND = 'No definition found in the glossary or Wikipedia/Wiktionary.';

function createCoinedProvider() {
  const standard = [createWikipediaProvider(), createWiktionaryProvider()];
  const firstUseOf = (term, ctx) => ctx?.registry?.firstUse?.(term, ctx?.sessionId ?? null) ?? null;

  return {
    id: 'coined',
    label: 'Coined-term fallback',
    canResolve(term, ctx) {
      if (normalizeTerm(term) === '') return false;
      return firstUseOf(term, ctx) !== null || typeof ctx?.fetch === 'function' || typeof ctx?.rest === 'function';
    },
    async resolve(term, ctx) {
      for (const provider of standard) {
        let found = null;
        try {
          found = await provider.resolve(term, ctx);
        } catch {
          found = null;
        }
        if (found) return null;
      }
      const first = firstUseOf(term, ctx);
      const quote = first && hasText_coined_provider(first.quote) ? first.quote : null;
      if (quote) {
        const sessionId = ctx?.sessionId ?? null;
        return {
          short: clipWords(quote, 25),
          long: 'inferred from context. ' + clipWords(quote, 120),
          source: 'First use in session',
          kind: 'coined',
          providerId: 'coined',
          url: null,
          firstUse: { quote, sessionId },
        };
      }
      return {
        short: NOT_FOUND,
        long: NOT_FOUND,
        source: 'Not found',
        kind: 'uncertain',
        providerId: 'coined',
        url: null,
        firstUse: null,
      };
    },
  };
}

// ---- src/llm-provider.js ----
const hasText_llm_provider = (v) => typeof v === 'string' && v.trim() !== '';

function createLlmProvider() {
  return {
    id: 'llm',
    label: 'LLM (backend)',
    canResolve(term, ctx) {
      return typeof ctx?.rest === 'function' && normalizeTerm(term) !== '';
    },
    async resolve(term, ctx) {
      let payload;
      try {
        payload = await ctx.rest('/define', {
          method: 'POST',
          body: { term, sessionId: ctx.sessionId ?? null, surrounding: ctx.surrounding ?? null },
        });
      } catch {
        return null;
      }
      if (payload == null || typeof payload !== 'object' || Array.isArray(payload)) return null;
      if (!hasText_llm_provider(payload.short) && !hasText_llm_provider(payload.long)) return null;
      const short = hasText_llm_provider(payload.short) ? payload.short : payload.long;
      const long = hasText_llm_provider(payload.long) ? payload.long : payload.short;
      return {
        ...payload,
        short: clipWords(short, 25),
        long: clipWords(long, 120),
        source: hasText_llm_provider(payload.source) ? payload.source : 'LLM',
        kind: payload.kind ?? 'uncertain',
        providerId: 'llm',
        url: payload.url ?? null,
        firstUse: payload.firstUse ?? null,
      };
    },
  };
}

// ---- src/termline.js ----
// Encodings for a whole sentence carried by one paragraph-level directive.
// Preferred: a plain sentence `v` plus `t="name=def;;name=def"`, which never
// puts `[`, `]` or `|` in the attribute (the host backslash-escapes those).
// Legacy: "A [[monoid|combines values]] lets you fold a list." inside `v`.
// Plain ESM with no imports so it can be concatenated into plugin.js.

const MARKER_OPEN = '[[';
const MARKER_SEP = '|';
const MARKER_CLOSE = ']]';

const UNSAFE = /[|[\]{}"'\\\r\n]/g;

// Keeps the marker encoding and the surrounding directive attribute body valid.
function sanitizeTermlinePart(s) {
  return String(s ?? '').replace(UNSAFE, '').trim();
}

const ESCAPED = /\\([\\`*_~[\]<>$&])/g;
const TERM_PAIR_SEP = ';;';

// Undoes the backslash escaping the host applies to inline markdown metachars
// in a directive body (`\[\[` arrives for `[[`).
function unescapeTermlineValue(s) {
  return typeof s === 'string' ? s.replace(ESCAPED, '$1') : '';
}

function parseTermline(value) {
  return scanMarkers(unescapeTermlineValue(value));
}

function scanMarkers(input) {
  const pieces = [];
  let text = '';
  const flush = () => {
    if (text !== '') pieces.push({ kind: 'text', text });
    text = '';
  };

  let pos = 0;
  while (pos < input.length) {
    const firstOpen = input.indexOf(MARKER_OPEN, pos);
    const close = firstOpen === -1 ? -1 : input.indexOf(MARKER_CLOSE, firstOpen + MARKER_OPEN.length);
    if (close === -1) break;
    // An earlier unmatched `[[` stays text; the marker is the nearest one before the close.
    const open = input.lastIndexOf(MARKER_OPEN, close - MARKER_OPEN.length);
    const inner = input.slice(open + MARKER_OPEN.length, close);
    const sep = inner.indexOf(MARKER_SEP);
    const name = (sep === -1 ? inner : inner.slice(0, sep)).trim();
    const def = sep === -1 ? '' : inner.slice(sep + MARKER_SEP.length).trim();
    if (name === '') {
      // Nothing to link: keep the characters so the sentence stays readable.
      text += input.slice(pos, open + MARKER_OPEN.length);
      pos = open + MARKER_OPEN.length;
      continue;
    }
    text += input.slice(pos, open);
    flush();
    pieces.push({ kind: 'term', name, def });
    pos = close + MARKER_CLOSE.length;
  }
  text += input.slice(pos);
  flush();

  const sentence = pieces.map((p) => (p.kind === 'term' ? p.name : p.text)).join('');
  return { pieces, sentence };
}

// `t` parts escape `\`, `;` and `=` with a backslash so a name or definition may hold them.
function escapeTermListPart(s) {
  return String(s ?? '').replace(/[\\;=]/g, '\\$&');
}

// Also removes the host's markdown backslashes (`\[`), which can reach a part unremoved.
function unescapeTermListPart(s) {
  return typeof s === 'string' ? s.replace(/\\([\\;=`*_~[\]<>$&])/g, '$1') : '';
}

// "monoid=def;;functor=def" -> [{ name, def }]. Splits on unescaped `;;`, then on the
// first unescaped `=` per pair, then unescapes each part.
function parseTermList(t) {
  const out = [];
  const input = typeof t === 'string' ? t : '';
  let name = null;
  let cur = '';
  const finish = () => {
    const n = unescapeTermListPart(name ?? cur).trim();
    if (n !== '') out.push({ name: n, def: name === null ? '' : unescapeTermListPart(cur).trim() });
    name = null;
    cur = '';
  };
  for (let i = 0; i < input.length; i++) {
    const ch = input[i];
    if (ch === '\\' && i + 1 < input.length) {
      cur += ch + input[++i];
    } else if (ch === ';' && input[i + 1] === ';') {
      finish();
      i++;
    } else if (ch === '=' && name === null) {
      name = cur;
      cur = '';
    } else {
      cur += ch;
    }
  }
  finish();
  return out;
}

const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Builds pieces from `{ v | text, t }`. Legacy `[[name|def]]` markers in the
// sentence win; otherwise each `t` name chips its first whole-word occurrence.
function materializeTermline(attrs) {
  const pick = (x) => (typeof x === 'string' ? unescapeTermlineValue(x).trim() : '');
  const sentenceText = pick(attrs?.v) || pick(attrs?.text);
  if (sentenceText === '') return { pieces: [], sentence: '' };
  const legacy = scanMarkers(sentenceText);
  if (legacy.pieces.some((p) => p.kind === 'term')) return legacy;

  let pieces = [{ kind: 'text', text: sentenceText }];
  const done = new Set();
  for (const { name, def } of parseTermList(attrs?.t)) {
    const key = name.toLowerCase();
    if (done.has(key)) continue;
    const re = new RegExp(
      `(?<![\\p{L}\\p{N}_])${escapeRe(name).replace(/\s+/g, '\\s+')}(?![\\p{L}\\p{N}_])`,
      'iu',
    );
    for (let i = 0; i < pieces.length; i++) {
      if (pieces[i].kind !== 'text') continue;
      const m = re.exec(pieces[i].text);
      if (!m) continue;
      const { text } = pieces[i];
      const next = [];
      if (m.index > 0) next.push({ kind: 'text', text: text.slice(0, m.index) });
      next.push({ kind: 'term', name: m[0], def });
      if (m.index + m[0].length < text.length) next.push({ kind: 'text', text: text.slice(m.index + m[0].length) });
      pieces = [...pieces.slice(0, i), ...next, ...pieces.slice(i + 1)];
      done.add(key);
      break;
    }
  }
  return { pieces, sentence: sentenceText };
}

const SAFE_HREF = /^(?:https?:\/\/|mailto:)[^\s()<>]+$/i;
const LINK_AT = /^\[([^[\]]+)\]\(([^()\s]+)\)/;
const isWord = (ch) => ch !== undefined && /[\p{L}\p{N}]/u.test(ch);
const isSpace = (ch) => ch === undefined || /\s/.test(ch);

const pushText = (nodes, text) => {
  if (text === '') return;
  const last = nodes[nodes.length - 1];
  if (last && last.kind === 'text') last.text += text;
  else nodes.push({ kind: 'text', text });
};

// Index of the first closing run for which `ok(index)` holds, hopping over code
// spans so a marker inside backticks never closes an outer span.
function findCloser(input, from, ok) {
  for (let j = from; j < input.length; j++) {
    if (input[j] === '`') {
      const end = input.indexOf('`', j + 1);
      if (end !== -1) j = end;
      continue;
    }
    if (ok(j)) return j;
  }
  return -1;
}

// Conservative inline markdown: **bold**, __bold__, *italic*, _italic_, `code`
// and [label](http(s)/mailto url). Anything that does not close cleanly stays
// literal text. Returns nodes of { kind: 'text', text } or
// { kind: 'strong' | 'em' | 'code' | 'link', children, href? }.
function parseInlineMarkdown(input, allowed = { strong: true, em: true, link: true }) {
  const s = typeof input === 'string' ? input : '';
  const nodes = [];
  let i = 0;
  const wrap = (kind, from, to, skip, extra, rules) => {
    const children = parseInlineMarkdown(s.slice(from, to), rules);
    nodes.push({ kind, ...extra, children });
    i = to + skip;
  };

  while (i < s.length) {
    const ch = s[i];

    if (ch === '`') {
      let run = 1;
      while (s[i + run] === '`') run++;
      const fence = '`'.repeat(run);
      const end = s.indexOf(fence, i + run);
      if (end > i + run && s[end + run] !== '`') {
        nodes.push({ kind: 'code', children: [{ kind: 'text', text: s.slice(i + run, end) }] });
        i = end + run;
        continue;
      }
      pushText(nodes, fence);
      i += run;
      continue;
    }

    if (ch === '!' && s[i + 1] === '[') {
      const img = LINK_AT.exec(s.slice(i + 1));
      if (img) {
        pushText(nodes, s.slice(i, i + 1 + img[0].length));
        i += 1 + img[0].length;
        continue;
      }
    }

    if (ch === '[' && allowed.link) {
      const m = LINK_AT.exec(s.slice(i));
      if (m && SAFE_HREF.test(m[2])) {
        const children = parseInlineMarkdown(m[1], { ...allowed, link: false });
        nodes.push({ kind: 'link', href: m[2], children });
        i += m[0].length;
        continue;
      }
    }

    if ((ch === '*' || ch === '_') && allowed.strong && allowed.em && s.startsWith(ch.repeat(3), i)
      && !isSpace(s[i + 3]) && (ch === '*' || !isWord(s[i - 1]))) {
      const close = findCloser(s, i + 3, (j) => s.startsWith(ch.repeat(3), j) && !isSpace(s[j - 1])
        && (ch === '*' || !isWord(s[j + 3])));
      if (close > i + 3) {
        nodes.push({
          kind: 'strong',
          children: [{ kind: 'em', children: parseInlineMarkdown(s.slice(i + 3, close), { strong: false, em: false, link: allowed.link }) }],
        });
        i = close + 3;
        continue;
      }
    }

    if ((ch === '*' || ch === '_') && s[i + 1] === ch) {
      const left = ch === '*' || !isWord(s[i - 1]);
      if (allowed.strong && left && !isSpace(s[i + 2]) && s[i + 2] !== ch) {
        const close = findCloser(s, i + 2, (j) => s[j] === ch && s[j + 1] === ch && s[j + 2] !== ch
          && !isSpace(s[j - 1]) && s[j - 1] !== ch && (ch === '*' || !isWord(s[j + 2])));
        if (close > i + 2) {
          wrap('strong', i + 2, close, 2, {}, { ...allowed, strong: false });
          continue;
        }
      }
      pushText(nodes, ch + ch);
      i += 2;
      continue;
    }

    if (ch === '*' || ch === '_') {
      const left = ch === '*' || !isWord(s[i - 1]);
      if (allowed.em && left && !isSpace(s[i + 1])) {
        const close = findCloser(s, i + 1, (j) => s[j] === ch && s[j - 1] !== ch && s[j + 1] !== ch
          && !isSpace(s[j - 1]) && (ch === '*' || !isWord(s[j + 1])));
        if (close > i + 1) {
          wrap('em', i + 1, close, 1, {}, { ...allowed, em: false });
          continue;
        }
      }
    }

    pushText(nodes, ch);
    i++;
  }
  return nodes;
}

const PH_OPEN = '\uE000';
const PH_CLOSE = '\uE001';
const PH_RE = /\uE000(\d+)\uE001/;

const textOf = (nodes) =>
  nodes.map((n) => (n.kind === 'text' ? n.text : n.kind === 'term' ? n.name : textOf(n.children))).join('');

// Replaces the first text leaf (document order) that `split` can break up.
function mapFirstLeaf(nodes, split) {
  for (let i = 0; i < nodes.length; i++) {
    const n = nodes[i];
    if (n.kind === 'text') {
      const parts = split(n.text);
      if (parts) return [...nodes.slice(0, i), ...parts, ...nodes.slice(i + 1)];
    } else if (n.kind !== 'term') {
      const kids = mapFirstLeaf(n.children, split);
      if (kids) return [...nodes.slice(0, i), { ...n, children: kids }, ...nodes.slice(i + 1)];
    }
  }
  return null;
}

function expandPlaceholders(nodes, terms) {
  return nodes.flatMap((n) => {
    if (n.kind === 'term') return [n];
    if (n.kind !== 'text') return [{ ...n, children: expandPlaceholders(n.children, terms) }];
    const out = [];
    let rest = n.text;
    for (let m = PH_RE.exec(rest); m; m = PH_RE.exec(rest)) {
      if (m.index > 0) out.push({ kind: 'text', text: rest.slice(0, m.index) });
      out.push({ kind: 'term', ...terms[Number(m[1])] });
      rest = rest.slice(m.index + m[0].length);
    }
    if (rest !== '') out.push({ kind: 'text', text: rest });
    return out;
  });
}

// Like materializeTermline, but the sentence is parsed as inline markdown first, so
// term chips can sit inside strong/em/a/code nodes and no marker characters leak
// into the neighbouring text. Returns { nodes, sentence } where `sentence` is the
// visible text.
function materializeInline(attrs) {
  const pick = (x) => (typeof x === 'string' ? unescapeTermlineValue(x).trim() : '');
  const sentenceText = pick(attrs?.v) || pick(attrs?.text);
  if (sentenceText === '') return { nodes: [], sentence: '' };

  const legacy = scanMarkers(sentenceText.replace(/[\uE000\uE001]/g, ''));
  if (legacy.pieces.some((p) => p.kind === 'term')) {
    const terms = [];
    const masked = legacy.pieces
      .map((p) => {
        if (p.kind === 'text') return p.text;
        terms.push({ name: p.name, def: p.def });
        return `${PH_OPEN}${terms.length - 1}${PH_CLOSE}`;
      })
      .join('');
    const nodes = expandPlaceholders(parseInlineMarkdown(masked), terms);
    return { nodes, sentence: textOf(nodes) };
  }

  let nodes = parseInlineMarkdown(sentenceText.replace(/[\uE000\uE001]/g, ''));
  const done = new Set();
  for (const { name, def } of parseTermList(attrs?.t)) {
    const key = name.toLowerCase();
    if (done.has(key)) continue;
    const re = new RegExp(
      `(?<![\\p{L}\\p{N}_])${escapeRe(name).replace(/\s+/g, '\\s+')}(?![\\p{L}\\p{N}_])`,
      'iu',
    );
    const next = mapFirstLeaf(nodes, (text) => {
      const m = re.exec(text);
      if (!m) return null;
      const parts = [];
      if (m.index > 0) parts.push({ kind: 'text', text: text.slice(0, m.index) });
      parts.push({ kind: 'term', name: m[0], def });
      if (m.index + m[0].length < text.length) parts.push({ kind: 'text', text: text.slice(m.index + m[0].length) });
      return parts;
    });
    if (next) {
      nodes = next;
      done.add(key);
    }
  }
  return { nodes, sentence: textOf(nodes) };
}

function formatTermline(pieces) {
  return (Array.isArray(pieces) ? pieces : [])
    .map((p) =>
      p?.kind === 'term'
        ? MARKER_OPEN + sanitizeTermlinePart(p.name) + MARKER_SEP + sanitizeTermlinePart(p.def) + MARKER_CLOSE
        : String(p?.text ?? ''),
    )
    .join('');
}

// ---- src/plugin-factory.js ----
// Plugin factory: wires providers to the Hermes SDK pieces injected by the caller.
// Plain ESM; no SDK, react or Node imports so it can run under node --test.


const PLUGIN_ID = 'concept-links';
const PANE_ID = 'glossary';
const SETTINGS_PANE_ID = 'providers';
const DIRECTIVE_NAME = 'term';
const TERMLINE_DIRECTIVE_NAME = 'termline';
const HOVER_DELAY_MS = 650;

const NO_DEF = 'No definition yet';
const CHIP_CLASS = 'inline cursor-pointer underline decoration-dotted underline-offset-2';
const PARAGRAPH_CLASS = 'leading-relaxed break-words';
// Inline so the chip does not depend on utilities missing from the Desktop CSS bundle (decoration-dotted).
const CHIP_STYLE = {
  display: 'inline',
  padding: 0,
  margin: 0,
  border: 'none',
  background: 'none',
  font: 'inherit',
  color: 'inherit',
  cursor: 'pointer',
  textDecoration: 'underline dotted',
  textUnderlineOffset: '2px',
};

const CODE_STYLE = { fontFamily: 'ui-monospace, monospace', fontSize: '0.9em' };

const SAMPLE_TERMLINE = {
  v: 'A monoid lets you fold a list in any grouping, and a functor maps over it.',
  t: 'monoid=A set with an associative operation and an identity element;;functor=A mapping between categories that preserves structure',
};

// attrs are untrusted model output: only trimmed strings are used.
const str = (v) => (typeof v === 'string' ? v.trim() : '');
const isThenable_plugin_factory = (v) => v != null && typeof v.then === 'function';

function createDefaultRegistry() {
  const registry = createRegistry();
  const session = createSessionProvider();
  session.bind(registry);
  for (const provider of [
    createInlineProvider(),
    session,
    createStaticProvider(),
    createMdnProvider(),
    createWiktionaryProvider(),
    createWikipediaProvider(),
    createCoinedProvider(),
    createLlmProvider(),
  ]) registry.register(provider);
  return registry;
}

function createPlugin(deps) {
  const { host, jsx, jsxs, atom, useValue, Tip, Button, ScrollArea, EmptyState, Badge, Switch, Separator } = deps;
  const registry = deps.registry ?? createDefaultRegistry();
  const fetchFn =
    deps.fetch ?? (typeof globalThis.fetch === 'function' ? (...args) => globalThis.fetch(...args) : undefined);

  const $selectedTerm = atom(null);
  const $prefsTick = atom(0);
  let storage = null;
  let rest;
  let userGlossary = [];
  let tick = 0;

  const sameTerm = (sel, name, sessionId) => sel && sel.name === name && sel.sessionId === sessionId;

  function persistPrefs() {
    const list = registry.list();
    storage?.set?.('providerPrefs', {
      order: list.map((p) => p.id),
      disabled: list.filter((p) => registry.isDisabled(p.id)).map((p) => p.id),
    });
    $prefsTick.set(++tick);
  }

  // The session provider replays recorded defs, so a disabled inline provider
  // must not leak its attribute def into the session store.
  const recordedDef = (def) => (def && !registry.isDisabled('inline') ? def : undefined);

  function makeChip({ name, def, sid, source, attrs, key }) {
    const lookupCtx = { sessionId: sid, attrs, source, userGlossary, fetch: fetchFn, rest };
    const sync = registry.lookupSync(name, lookupCtx);

    const text = sync?.short || NO_DEF;
    const label = jsxs('div', {
      children: [
        jsx('span', { children: text }),
        sync?.source ? jsx('span', { className: 'block text-xs opacity-70', children: sync.source }) : null,
        sync?.kind === 'coined' ? jsx(Badge, { children: 'coined' }) : null,
      ].filter(Boolean),
    });

    const onClick = (event) => {
      // A chip inside a markdown link must not also follow the link.
      event?.preventDefault?.();
      $selectedTerm.set({ name, sessionId: sid, definition: sync });
      if (typeof host?.revealPane === 'function') host.revealPane(`${PLUGIN_ID}:${PANE_ID}`);
      let pending;
      try {
        pending = Promise.resolve(registry.lookup(name, lookupCtx));
      } catch {
        return;
      }
      pending.then(
        (found) => {
          if (found && sameTerm($selectedTerm.get(), name, sid)) {
            $selectedTerm.set({ name, sessionId: sid, definition: found });
          }
        },
        () => {},
      );
    };

    const chip = jsx('button', { type: 'button', onClick, className: CHIP_CLASS, style: CHIP_STYLE, children: name });
    return jsx(Tip, { delayDuration: HOVER_DELAY_MS, label, children: chip }, key);
  }

  // Mid-sentence use still works for old chats and models that ignore the skill,
  // but the Desktop host splits a paragraph around every claimed directive
  // (markdown-text.tsx, MarkdownParagraph), so the chip lands in its own block.
  // Whole sentences go through `termline` instead.
  function renderTerm({ attrs, source, streaming, sessionId } = {}) {
    useValue($prefsTick);
    const name = str(attrs?.name);
    if (!name) return jsx('span', { children: source });
    const def = str(attrs?.def);
    const sid = sessionId ?? null;
    if (!streaming) registry.recordUse({ name, def: recordedDef(def), sessionId: sid, source, attrs });
    return makeChip({ name, def, sid, source, attrs });
  }

  function renderTermline({ attrs, source, streaming, sessionId } = {}) {
    useValue($prefsTick);
    const parsed = materializeInline(attrs);
    if (!parsed.nodes.length) return jsx('span', { children: source });
    const sid = sessionId ?? null;
    const build = (nodes, path) =>
      nodes.map((node, i) => {
        if (node.kind === 'text') return node.text;
        const key = `${path}${i}`;
        if (node.kind === 'term') {
          const { name, def } = node;
          const termAttrs = { name, def };
          if (!streaming) {
            registry.recordUse({
              name,
              def: recordedDef(def),
              sessionId: sid,
              source,
              attrs: termAttrs,
              surrounding: parsed.sentence,
            });
          }
          return makeChip({ name, def, sid, source, attrs: termAttrs, key: `t${key}` });
        }
        const children = build(node.children, `${key}.`);
        if (node.kind === 'strong') return jsxs('strong', { children }, `s${key}`);
        if (node.kind === 'em') return jsxs('em', { children }, `s${key}`);
        if (node.kind === 'code') return jsxs('code', { style: CODE_STYLE, children }, `s${key}`);
        return jsxs('a', { href: node.href, target: '_blank', rel: 'noreferrer noopener', children }, `s${key}`);
      });
    const children = build(parsed.nodes, '');
    // Not a <p>: the host already gives a solo directive its own block, but
    // only host <p> elements get the paragraph gap, so mirror it here.
    return jsxs('span', {
      className: PARAGRAPH_CLASS,
      style: { display: 'block', marginBlock: 'var(--paragraph-gap) 0' },
      children,
    });
  }

  // Rows for the provider list. Shared by the Concepts pane and the standalone
  // settings pane because the host may never tab the second pane.
  function providerRows() {
    useValue($prefsTick);
    const list = registry.list();
    const setDisabledFor = (id, off) => {
      const next = list.map((p) => p.id).filter((pid) => (pid === id ? off : registry.isDisabled(pid)));
      registry.setDisabled(next);
      persistPrefs();
    };
    const move = (index, delta) => {
      const ids = list.map((p) => p.id);
      const to = index + delta;
      if (to < 0 || to >= ids.length) return;
      [ids[index], ids[to]] = [ids[to], ids[index]];
      registry.setOrder(ids);
      persistPrefs();
    };
    const rows = [];
    list.forEach((provider, index) => {
      const enabled = !registry.isDisabled(provider.id);
      if (index > 0) rows.push(jsx(Separator, {}, `sep-${provider.id}`));
      rows.push(
        jsxs(
          'div',
          {
            className: 'flex items-center gap-2',
            children: [
              jsx('span', { className: 'flex-1 text-sm', children: `${provider.label} (${provider.id})` }),
              jsx(Switch, {
                checked: enabled,
                'aria-label': `Enable ${provider.label}`,
                onCheckedChange: (on) => setDisabledFor(provider.id, !on),
                onClick: () => setDisabledFor(provider.id, enabled),
              }),
              jsx(Button, { type: 'button', onClick: () => move(index, -1), children: 'Up' }),
              jsx(Button, { type: 'button', onClick: () => move(index, 1), children: 'Down' }),
            ],
          },
          provider.id,
        ),
      );
    });
    return rows;
  }

  function providersSection() {
    return jsxs('div', {
      className: 'flex flex-col gap-2',
      children: [jsx('h3', { className: 'text-sm font-semibold', children: 'Providers' }), ...providerRows()],
    });
  }

  function renderPane() {
    const selected = useValue($selectedTerm);
    const section = providersSection();
    const wrap = (children) =>
      jsx(ScrollArea, { children: jsxs('div', { className: 'flex flex-col gap-3 p-4', children }) });
    if (!selected) {
      return wrap([
        jsx(EmptyState, {
          title: 'No concept selected',
          description: 'Click a dotted term in the chat to see it here.',
        }),
        jsx(Separator, {}),
        jsxs('div', {
          className: 'flex flex-col gap-2',
          children: [
            jsx('h3', { className: 'text-sm font-semibold', children: 'Sample' }),
            // An element, not a call: renderTermline's hook must not join this
            // pane's hooks, or the count changes when a term gets selected.
            jsx(renderTermline, {
              attrs: SAMPLE_TERMLINE,
              source: '::termline',
              streaming: true,
              sessionId: 'sample',
            }),
          ],
        }),
        jsx(Separator, {}),
        section,
      ]);
    }
    const { name, sessionId, definition } = selected;
    const hasQuote = (v) => typeof v === 'string' && v.trim() !== '';
    const defTexts = [definition?.short, definition?.long].filter(hasQuote).map((t) => t.trim());
    const quotes = registry
      .usesFor(name, sessionId)
      .map((u) => u.quote)
      .filter(hasQuote);
    const fromDefinition = definition?.firstUse?.quote;
    const first =
      quotes[0] ?? (hasQuote(fromDefinition) && !defTexts.includes(fromDefinition.trim()) ? fromDefinition : null);
    const firstText = first ? first.trim() : null;
    const laterQuotes = [...new Set(quotes.map((q) => q.trim()))].filter((q) => q !== firstText);
    const kind = definition?.kind;
    return wrap(
      [
        jsx('h2', { className: 'text-base font-semibold', children: name }),
        kind === 'coined' || kind === 'uncertain' ? jsx(Badge, { children: kind }) : null,
        jsx('p', { className: 'text-sm', children: definition?.long || definition?.short || NO_DEF }),
        definition?.source ? jsx('p', { className: 'text-xs opacity-70', children: `Source: ${definition.source}` }) : null,
        definition?.providerId
          ? jsx('p', { className: 'text-xs opacity-70', children: `Provider: ${definition.providerId}` })
          : null,
        first ? jsx('p', { className: 'text-sm', children: `First use in this session: ${first}` }) : null,
        laterQuotes.length
          ? jsxs('div', {
              children: [
                jsx('h3', { className: 'text-sm font-semibold', children: 'Uses in this session' }),
                jsx('ul', {
                  className: 'text-sm',
                  children: laterQuotes.map((q, i) => jsx('li', { children: q }, i)),
                }),
              ],
            })
          : null,
        jsx(Button, { type: 'button', onClick: () => $selectedTerm.set(null), children: 'Clear' }),
        jsx(Separator, {}),
        section,
      ].filter(Boolean),
    );
  }

  function renderSettings() {
    return jsx(ScrollArea, { children: jsxs('div', { className: 'flex flex-col gap-2 p-4', children: providerRows() }) });
  }

  function applyPrefs(prefs) {
    if (prefs && typeof prefs === 'object') {
      if (Array.isArray(prefs.order)) registry.setOrder(prefs.order);
      if (Array.isArray(prefs.disabled)) registry.setDisabled(prefs.disabled);
    }
    $prefsTick.set(++tick);
  }

  function applyGlossary(value) {
    if (Array.isArray(value) || (value && typeof value === 'object')) userGlossary = value;
  }

  // Storage may be sync or promise-based; handle both.
  const read = (key, fallback, apply) => {
    let value;
    try {
      value = storage.get(key);
    } catch {
      return;
    }
    if (isThenable_plugin_factory(value)) value.then((v) => apply(v ?? fallback), () => {});
    else apply(value ?? fallback);
  };

  function register(ctx) {
    rest = ctx?.rest;
    storage = ctx?.storage ?? null;
    ctx.register({ id: DIRECTIVE_NAME, area: 'transcript.directives', data: { name: DIRECTIVE_NAME, render: renderTerm } });
    ctx.register({
      id: TERMLINE_DIRECTIVE_NAME,
      area: 'transcript.directives',
      data: { name: TERMLINE_DIRECTIVE_NAME, render: renderTermline },
    });
    ctx.register({
      id: PANE_ID,
      area: 'panes',
      title: 'Concepts',
      data: { placement: 'right', width: '340px' },
      render: renderPane,
    });
    ctx.register({
      id: SETTINGS_PANE_ID,
      area: 'panes',
      title: 'Concept providers',
      data: { placement: 'right', width: '340px' },
      render: renderSettings,
    });
    ctx.register({
      id: 'open-concepts',
      area: 'palette',
      data: {
        id: 'open-concepts',
        label: 'Open concepts pane',
        keywords: ['concept', 'term', 'glossary', 'definition'],
        run: () => {
          if (typeof host?.revealPane === 'function') host.revealPane(`${PLUGIN_ID}:${PANE_ID}`);
        },
      },
    });
    ctx.register({
      id: 'open-provider-settings',
      area: 'palette',
      data: {
        id: 'open-provider-settings',
        label: 'Concept provider settings',
        keywords: ['provider', 'settings', 'glossary', 'concept'],
        run: () => {
          if (typeof host?.revealPane === 'function') host.revealPane(`${PLUGIN_ID}:${PANE_ID}`);
          if (typeof host?.undismissPane === 'function') host.undismissPane(`${PLUGIN_ID}:${SETTINGS_PANE_ID}`);
          if (typeof host?.revealPane === 'function') host.revealPane(`${PLUGIN_ID}:${SETTINGS_PANE_ID}`);
        },
      },
    });
    if (storage) {
      read('providerPrefs', {}, applyPrefs);
      read('userGlossary', [], applyGlossary);
    }
  }

  return {
    register,
    registry,
    $selectedTerm,
    $prefsTick,
    renderTerm,
    renderTermline,
    renderPane,
    renderSettings,
    PLUGIN_ID,
    PANE_ID,
    SETTINGS_PANE_ID,
    DIRECTIVE_NAME,
    TERMLINE_DIRECTIVE_NAME,
    HOVER_DELAY_MS,
  };
}

const _plugin = createPlugin({
  host,
  jsx,
  jsxs,
  atom,
  useValue,
  Tip,
  Button,
  ScrollArea,
  EmptyState,
  Badge,
  Switch,
  Separator,
})

export default {
  id: 'concept-links',
  name: 'Concept Links',
  register(ctx) {
    _plugin.register(ctx)
  },
}
